const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch({
    headless: true,
    executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  });

  async function capture(width, height, outName) {
    const page = await browser.newPage({ viewport: { width, height } });
    await page.addInitScript(() => {
      localStorage.setItem('simplify-viewer-tour-v1', '1');
      localStorage.removeItem('simplify-viewer-playback-tour-v1');
    });
    await page.goto('http://127.0.0.1:5050/?t=' + Date.now(), { waitUntil: 'domcontentloaded' });

    // Dismiss start tour if it still appears
    const skip = page.locator('#uiTourSkip');
    if (await skip.isVisible().catch(() => false)) await skip.click();

    if (width <= 720) {
      const trigger = page.locator('#preloadedTrigger');
      if (await trigger.isVisible().catch(() => false)) {
        await trigger.click();
        await page.waitForTimeout(200);
        const opt = page.locator('[data-value="1"], .preloaded-option, .trace-picker-list button').first();
        if (await opt.count()) await opt.click();
        else await page.selectOption('#traceSelect', '1');
      } else {
        await page.selectOption('#traceSelect', '1');
      }
    } else {
      await page.selectOption('#traceSelect', '1');
    }

    await page.click('#loadBtn');
    await page.waitForFunction(
      () => document.body.classList.contains('playback-ready') ||
            (document.querySelector('#uploadStatus')?.textContent || '').includes('Loaded'),
      { timeout: 180000 }
    );
    await page.waitForTimeout(600);

    // Wait for playback tour card
    await page.waitForSelector('#uiTour:not([hidden])', { timeout: 15000 });
    // Advance to Results step (4/4)
    for (let i = 0; i < 3; i++) {
      await page.click('#uiTourNext');
      await page.waitForTimeout(250);
    }
    const title = await page.locator('#uiTourTitle').textContent();
    const stepLabel = await page.locator('#uiTourStepLabel').textContent();
    const resultsVisible = await page.evaluate(() => {
      const btn = document.getElementById('resultsPanelOpen');
      if (!btn) return false;
      const style = getComputedStyle(btn);
      const rect = btn.getBoundingClientRect();
      return style.display !== 'none' && rect.width > 1 && rect.height > 1 &&
             document.body.classList.contains('results-available');
    });
    const rejected = await page.evaluate(() => {
      const label = document.querySelector('label[for="toggle-dead-candidates"], #toggle-dead-candidates')?.closest('label');
      return label ? label.textContent.trim() : null;
    });
    console.log(JSON.stringify({ width, title, stepLabel, resultsVisible, rejected }));
    await page.screenshot({
      path: path.join('web/usability', outName),
      fullPage: false,
    });
    await page.close();
  }

  await capture(1280, 800, 'results-tour-1280-live.png');
  await capture(390, 844, 'results-tour-390-live.png');
  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });
